import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"38、【睽】 兌下離上","description":"周易集註 - 38、【睽】 兌下離上","frontmatter":{"title":"38、【睽】 兌下離上","description":"周易集註 - 38、【睽】 兌下離上"},"headers":[],"relativePath":"classics/jizhu/042.md","filePath":"classics/jizhu/042.md"}'),t={name:"classics/jizhu/042.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_38、【睽】-兌下離上" tabindex="-1">38、【睽】 兌下離上 <a class="header-anchor" href="#_38、【睽】-兌下離上" aria-label="Permalink to “38、【睽】 兌下離上”">​</a></h1><p>睽字從目，目少睛也。目主見，故周公爻辭，初曰見惡人，三曰見輿曳，上曰見豕負塗，皆見字之意。若從耳，亦曰聧，蓋耳聾之甚也。睽，乖異也。為卦上離下兌，火炎上，澤潤下，二體相違，睽之義也。又中少二女同居，志不同，亦睽之義也。《序卦》：家道窮必乖，故受之以睽。家道窮者，教家之道理窮絕也，無教家之道理，則乖異矣，所以次家人。睽綜家人，家人離之陰在二，巽之陰在四，皆得其正。睽則兌之陰居三，離之陰居五，皆居陽位，不得其正。不正，則家道窮，故曰家道窮必乖，故受之以睽。</p><p>《彖》曰：睽，火動而上，澤動而下，二女同居，其志不同行。說而麗乎明，柔進而上行，得中而應乎剛，是以小事吉。天地睽，而其事同也;男女睽，而其志通也;萬物睽，而其事類也。睽之時用大矣哉!</p><p>以卦象卦德卦綜卦體，釋卦名卦辭，極言其理而贊之。火燥炎上，澤溼就下，物性本然之睽。中女配坎，少女配艮，人情必然之睽，故名睽。兌說，離明，說麗乎明也。柔進而上行者，睽綜家人，二卦同體，文王綜為一卦，故《雜卦》曰：“睽外也，家人內也。”言家人下卦之離，進而為睽之上卦。六得乎五之中，而下應乎九二之剛也，三者皆柔之所為。柔本不能濟事，又當睽乖之時，何由得小事吉?然說麗明則有德，進乎五則有位，應乎剛則有輔，因有此三者，是以小事吉也。事同者，知始作成化育之事同也。志通者，夫唱婦隨，交感之情通也。事類者，聲應氣求，感應之機類也。天地不睽，不能成造化。男女不睽，不能成人道。萬物不睽，不能成物類。此其時用所以大也，與坎蹇同。</p><h3 id="《象》曰-上火下澤-睽-君子以同而異。" tabindex="-1">《象》曰：上火下澤，睽，君子以同而異。 <a class="header-anchor" href="#《象》曰-上火下澤-睽-君子以同而異。" aria-label="Permalink to “《象》曰：上火下澤，睽，君子以同而異。”">​</a></h3><p>同者理，異者事，天下無不同之理，而有不同之事。異其事而同其理，所以同而異。如禹稷顏回同道，而出處異。微子比干箕子同仁，而去就死生異是也。《彖》辭言異而同，《象》辭言同而異，此所以為聖人之言也。</p><p>初九，悔亡，喪馬勿逐自復，見惡人無咎。喪息浪反</p><p>喪者喪去也。中爻坎，為亟心之馬，馬亟心，倏然喪去，喪馬之象也。勿逐自復者，不追逐而自還也。兌為悅體，凡易中言兌者，皆勿逐自復：如震之六二變兌，亦勿逐，七日得。既濟六二變兌，亦勿逐，七日得是也。坎為盜，惡人之象也。中爻應爻離，持戈兵，亦惡人之象也。故大有初爻曰無交害，三爻曰小人害也。曰小人，則指離矣。見惡人者，惡人來而我即見之，不以惡人而拒絕也。離為目，見之象也。</p><p>初九當睽乖之時，上無應與相援，若有悔矣。然陽剛得正，故佔者悔亡。但時正當睽，不可強求人之必合，故必去者不追，惟聽其自還;來者不拒，雖惡人亦見之。此善於處睽者也。能如是，則悔亡而無咎矣，故又教佔者，佔中之象如此。</p><h3 id="《象》曰-見惡人-以闢咎也。闢音避" tabindex="-1">《象》曰：見惡人，以闢咎也。闢音避 <a class="header-anchor" href="#《象》曰-見惡人-以闢咎也。闢音避" aria-label="Permalink to “《象》曰：見惡人，以闢咎也。闢音避”">​</a></h3><p>當睽之時，行動即有咎病，故惡人亦不拒絕，而見之者，所以避咎也，咎即睽乖之咎。</p><p>九二，遇主於巷，無咎。</p><p>遇者相逢也，詳見噬嗑六三遇毒。巷有二，街巷也，里巷也。兌錯艮，艮為徑路，里巷之象也。應爻離中虛，街巷之象也。離為日，主之象也。當睽之時，君臣相求，必欲拘堂陛之常分，則賢者無自而進矣。遇主於巷者，言不在廊廟之上，而在於巷道之中，如鄧禹諸臣之遇光武是也。</p><p>九二以剛中而居悅體，上應六五，六五正當人心睽乖之時，柔弱已甚，欲思賢明之人以輔之。二以悅體，兩情相合，正所謂得中而應乎剛也，故有遇主於巷之象。佔者得此，睽而得合矣，故無咎。</p><h3 id="《象》曰-遇主於巷-未失道也。" tabindex="-1">《象》曰：遇主於巷，未失道也。 <a class="header-anchor" href="#《象》曰-遇主於巷-未失道也。" aria-label="Permalink to “《象》曰：遇主於巷，未失道也。”">​</a></h3><p>本卦離為戈兵，中爻離，亦為戈兵。兌為毀折，中爻又為坎陷。言君臣相遇於巷，豈不失道哉?然當天下睽乖之時，外而前有戈兵，後有戈兵，中原坎陷;內而主又柔弱，國勢毀折，分崩離析，正危迫之秋，非但君擇臣，臣亦擇君時也。得一豪傑之士，即足以濟睽矣，況又正應乎。聖人見得有此象，所以周公許其無咎，孔子許其未失道也，所以易經要玩象。</p><p>六三，見輿曳，其牛掣，其人天且劓，無初有終。掣音徹，劓魚器反</p><p>上卦離為目，見之象也。見者六三與上九並見之也。又為牛，牛之象也。中爻坎，輿之象也，曳之象也。曳者拖也引也。掣者挽也，兌錯艮為手，挽之象也。其人天者，指六三與上九也。六三陰也，居人位，故曰人。上九陽也，居天位，故曰天。周公爻辭之玄至此。錯艮，又為鼻，鼻之象也。刑割鼻曰劓，鼻之上有戈兵，劓之象也。艮又為閽寺，刑人不曰閽寺，而曰劓者，戈兵之刑，在卦之上體也。若閽寺，則在下體矣，然非真割鼻也。鼻者通氣出入之物，六三上九本乃正應，見其曳掣，怒氣之發，如割鼻然，故取此象。且者未定之辭，言非真割鼻也。大意言車前必有牛，六三在車中，後二曳其車，前四掣其牛，所以上九見之而發怒也，此正所謂無初也。此皆本爻自有之象，易惟有此象，無此事，如入於左腹之類是也。後儒不悟象，所以將此等險辭，通鶻突放過去了。</p><p>六三不中不正，上應上九，欲與之合，然當睽乖之時，承乘皆不正之陽，亦欲與之相合，曳掣不能行，上下正應，見其曳掣，不勝其怒，故有此象。然陰陽正應，初雖睽乖，而終得合也，故其象佔如此。</p><h3 id="《象》曰-見輿曳-位不當也。無初有終-遇剛也。" tabindex="-1">《象》曰：見輿曳，位不當也。無初有終，遇剛也。 <a class="header-anchor" href="#《象》曰-見輿曳-位不當也。無初有終-遇剛也。" aria-label="Permalink to “《象》曰：見輿曳，位不當也。無初有終，遇剛也。”">​</a></h3><p>陰居陽位，故不當。遇剛者，遇上九也。</p><p>九四，睽孤，遇元夫。交孚，厲無咎。</p><p>元者大也，夫者人也。陽為大人，陰為小人，指初為大人也。交孚者，同德相信也。厲者，競競然危心以處之，惟恐交孚之不至也。</p><p>九四以陽剛當睽之時，左右之鄰皆陰柔之小人，孤立而無助者也，故有睽孤之象。然性本離明，知初九為大人君子，與之同德相信，故又有遇元夫交孚之象。然必危心以處之，方可無咎。故又教佔者如此。</p><h3 id="《象》曰-交孚無咎-志行也。" tabindex="-1">《象》曰：交孚無咎，志行也。 <a class="header-anchor" href="#《象》曰-交孚無咎-志行也。" aria-label="Permalink to “《象》曰：交孚無咎，志行也。”">​</a></h3><p>志行者，二陽同德而相與濟睽之志行也。蓋睽者乖之極，孤者睽之極，二德交孚，則睽者可合，孤者有朋，志可行，而難可濟，不特無咎而已也。</p><p>六五，悔亡，厥宗噬膚，往何咎?</p><p>宗字詳見同人六二，噬膚詳見噬嗑六二。言相合甚易，如噬膚之柔脆也。九二遇主於巷，曰主者，尊之也。六五厥宗噬膚，曰宗者，親之也。臣尊其君，君親其臣，豈不足以濟天下之睽。</p><p>六五當睽之時，以柔居尊，宜有悔矣，然質本文明，柔進上行，有柔中之德。下應剛中之賢，而虛己下賢之心甚篤，故悔可亡，有厥宗噬膚之象。惟其合之甚易，所以悔亡也。佔者以是而往，睽可濟矣，故無咎也。</p><h3 id="《象》曰-厥宗噬膚-往有慶也。" tabindex="-1">《象》曰：厥宗噬膚，往有慶也。 <a class="header-anchor" href="#《象》曰-厥宗噬膚-往有慶也。" aria-label="Permalink to “《象》曰：厥宗噬膚，往有慶也。”">​</a></h3><p>往則可以濟睽，故有慶。</p><p>上九，睽孤，見豕負塗，載鬼一車，先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。說吐活反</p><p>九四之孤，以人而孤也，因左右皆陰爻也。上九之孤，自孤也，因猜疑而孤也。見者上九自見之而疑也，負者背也，塗者泥也。離錯坎，坎為豕，又為水，豕負塗之象也。坎為隱伏，載鬼之象也。又為弓，又為狐疑，張弓說弓，心狐疑不定之象也。變震為歸妹，男悅女，女悅男，婚媾之象也。寇指九二九四，又坎為雨，雨之象也。遇雨者，遇六三也，雨則三之象也。三居澤之上，乃雨也。</p><p>上九以陽剛處明，終睽極之地，猜疑難合，故為睽孤。與六三本為正應，始見六三輿曳牛掣，乃疑其為豕，又疑其非豕而為鬼，方欲張弓射之，又疑其非鬼，乃脫弓而近於前，乃六三也。使非二四之寇，上則早與六三成其婚媾矣。始雖睽孤，終而群疑亡，又復相合，故有此象。往遇雨，又婚媾之象也。佔者凡事必如是則吉。</p><h3 id="《象》曰-遇雨之吉-群疑亡也。" tabindex="-1">《象》曰：遇雨之吉，群疑亡也。 <a class="header-anchor" href="#《象》曰-遇雨之吉-群疑亡也。" aria-label="Permalink to “《象》曰：遇雨之吉，群疑亡也。”">​</a></h3><p>惟群疑亡，所以遇雨吉。</p>',36)])])}const f=e(t,[["render",h]]);export{_ as __pageData,f as default};
